function readinessDetail(readiness){return readiness<20?"備戰度不足，今日不可派遣":readiness<40?"疲憊出勤，今日成效為 70%":"狀態良好，可以正常出勤";}
function deploymentView(){const assignments=state.team.deployment.assignments,cards=state.team.roster.map(member=>{const person=characterVisual(member.id),assignment=assignments[member.id],readiness=member.readiness??100,unavailable=readiness<20;return `<article class="deployment-card ${assignment?"deployed":"reserve"} ${unavailable?"unavailable":""}" data-deployment-member="${member.id}">${characterImage(member.id,"deployment-portrait")}<div class="deployment-card-copy"><div class="deployment-card-heading"><span class="tag">${assignment?"已派遣":"保留待命"}／Lv.${state.characterLevels[member.id]||member.level||1}</span><h3>${esc(person?.name||member.id)}</h3><small>${esc(person?.role||"核心隊員")}</small></div><div class="readiness" aria-label="備戰度 ${readiness}／100"><span>備戰度 ${readiness}/100</span><i style="width:${Math.max(0,Math.min(100,readiness))}%"></i><small class="${unavailable?"danger":"muted"}">${readinessDetail(readiness)}</small></div><label>今日任務<select data-deployment-type="${member.id}" aria-label="${esc(person?.name||member.id)}的今日任務" ${unavailable?"disabled":""}>${deploymentTypeOptions(assignment?.type)}</select></label>${deploymentTargetControl(member.id,assignment)}</div></article>`;}).join("");return `<section class="panel deployment-panel"><div class="tag accent">第 ${state.day} 日／上午部署</div><h2>狄菲的每日派遣</h2><p>${esc(deploymentReason(state))}</p><div class="deployment-grid">${cards}</div><div class="deployment-controls" aria-label="每日派遣操作"><button class="secondary" data-deployment-recommend>採用狄菲建議</button><button class="primary" data-deployment-confirm>確認今日派遣</button></div>${autoMode==="off"?automationControls():""}</section>`;}
