  if(!state&&!document.querySelector("[data-start-modifier]")){const button=document.createElement("button");button.className="secondary";button.dataset.startModifier="";button.textContent="開啟遊戲修改器";document.querySelector(".actions")?.append(button);button.addEventListener("click",()=>{stopAutomation();clearMarketCart();state=newGame("不公開",Date.now()>>>0);modifierOpen=true;persist();render();});}
