  document.querySelector("[data-start]")?.addEventListener("click",()=>{const seed=(Date.now()>>>0);stopAutomation();clearMarketCart();state=newGame("不公開",seed);persist();render();});
  document.querySelector("[data-load]")?.addEventListener("click",()=>{try{stopAutomation();clearMarketCart();state=validateSave(JSON.parse(localStorage.getItem(SAVE_KEY)));persist();render();}catch(e){stopAutomation();error=e.message;localStorage.removeItem(SAVE_KEY);start();}});
  document.querySelectorAll("[data-assistant-hide]").forEach(button=>button.addEventListener("click",()=>{assistantVisible=false;localStorage.setItem(ASSISTANT_KEY,"hidden");render();}));
