  document.querySelectorAll("[data-assistant-action]").forEach(checkbox=>checkbox.addEventListener("change",event=>{const next=new Set(assistantActions),id=event.currentTarget.value;if(event.currentTarget.checked)next.add(id);else next.delete(id);if(!next.size)return;assistantActions=[...next];assistantPickerOpen=true;localStorage.setItem(ASSISTANT_ACTIONS_KEY,JSON.stringify(assistantActions));render();}));
  document.querySelectorAll("[data-assistant-preset]").forEach(button=>button.addEventListener("click",()=>{assistantActions=button.dataset.assistantPreset==="all"?ASSISTANT_ACTION_OPTIONS.map(option=>option.id):[...DEFAULT_ASSISTANT_ACTIONS];assistantPickerOpen=true;localStorage.setItem(ASSISTANT_ACTIONS_KEY,JSON.stringify(assistantActions));render();}));
  document.querySelector("[data-assistant-accept]")?.addEventListener("click",event=>{const adviceId=event.currentTarget.dataset.assistantAccept;if(adviceId.startsWith("battle:")){void playBattleAction(adviceId.slice(7),beforeState=>acceptAssistantAdvice(beforeState,adviceId,assistantActions));return;}commit(()=>acceptAssistantAdvice(state,adviceId,assistantActions));});
  document.querySelectorAll("[data-deployment-type]").forEach(select=>select.addEventListener("change",()=>{const memberId=select.dataset.deploymentType;if(select.value==="reserve"){commit(()=>updateDeploymentAssignment(state,memberId,null));return;}const targetId=select.value==="manage"?state.assets.industries[0]?.id:select.value==="defend"?controlledTerritories(state)[0]?.id:null;commit(()=>updateDeploymentAssignment(state,memberId,{type:select.value,targetId}));}));
