  document.querySelector("[data-city-map]")?.addEventListener("click",event=>{const node=event.target.closest("[data-map-territory]"),cardLink=event.target.closest("[data-map-card]");if(node)updateCityMapSelection(node.dataset.mapTerritory);if(cardLink)focusTerritoryCard(cardLink.dataset.mapCard);});
  document.querySelectorAll("[data-choice]").forEach(el=>el.addEventListener("click",()=>commit(()=>resolveChoice(state,el.dataset.choice))));
  document.querySelectorAll("[data-character-event]").forEach(el=>el.addEventListener("click",()=>commit(()=>startCharacterEvent(state,el.dataset.characterEvent))));
  document.querySelectorAll("[data-character-choice]").forEach(el=>el.addEventListener("click",()=>commit(()=>resolveCharacterEventChoice(state,el.dataset.characterChoice))));
  document.querySelectorAll("[data-market-purchase]").forEach(button=>button.addEventListener("click",()=>toggleMarketLine({kind:"purchase",choiceId:button.dataset.marketPurchase})));
  document.querySelectorAll("[data-market-upgrade]").forEach(button=>button.addEventListener("click",()=>{const [category,assetId,expectedLevel]=button.dataset.marketUpgrade.split(":");toggleMarketLine({kind:"upgrade",category,assetId,expectedLevel:Number(expectedLevel)});}));
  document.querySelector("[data-market-clear]")?.addEventListener("click",()=>{clearMarketCart();render();});
  document.querySelector("[data-market-checkout]")?.addEventListener("click",()=>{if(marketCheckoutRunning)return;marketCheckoutRunning=true;const lines=structuredClone(marketCart);commit(()=>checkoutMarket(state,lines));if(state.phase==="result")clearMarketCart();});
